// Round, chubby look for 128px animal sheets: wider squashed body, soft bounce and a round shadow.
// The source pixel art is kept (nearest-neighbour); only the drawing transform changes.
export function paintCute(canvas,image,frame,row,{time=0,walking=false,size=128,reduced=false}={}){if(!canvas?.getContext||!image)return;const c=canvas.getContext('2d');if(!c)return;c.setTransform(1,0,0,1,0,0);c.clearRect(0,0,size,size);c.imageSmoothingEnabled=false;const hop=reduced?0:walking?Math.abs(Math.sin(time*9))*6:0,breathe=reduced?0:Math.sin(time*2.6)*.025,squash=walking?.04*Math.cos(time*18):0,sx=1.16+breathe-squash,sy=.88-breathe+squash,foot=size*.9;c.fillStyle='rgba(84,104,78,.18)';c.beginPath();c.ellipse(size/2,foot,size*.3*(1-hop/30),size*.07,0,0,Math.PI*2);c.fill();c.translate(size/2,foot-hop);c.scale(sx*size/128,sy*size/128);c.drawImage(image,frame*128,row*128,128,128,-64,-116,128,128);c.setTransform(1,0,0,1,0,0);}
